{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Canrenone, the closest structural analogue sharing the 3-one-4-ene and 17-spirolactone system, showed approximately 98% oral bioavailability in humans, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Eplerenone, another 17-spirolactone steroid closely related to the query, has an absolute oral bioavailability of about 98% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Hydrocortisone, a structurally related 3-one-4-ene steroid, showed absolute oral bioavailability of about 93% in healthy volunteers, supporting high F for this steroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Cortisone, another close steroid analogue, had an oral bioavailability of about 85% in humans, further supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Testosterone has very low absolute oral bioavailability (~3.7%), but it lacks the 17-spirolactone moiety and is much less transferable to the query; this is contradictory but low-weight evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Medroxyprogesterone acetate has low oral bioavailability (<15%), but its 17-acetate and lack of the spirolactone system make it a poor model for the query; this is contradictory but low-weight evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a drospirenone-type 17-spirolactone steroid. The closest analogues with the same spirolactone and enone system—canrenone and eplerenone—show near-complete oral bioavailability, and other steroid analogues such as hydrocortisone and cortisone also show high F. Low-bioavailability analogues like testosterone and medroxyprogesterone acetate lack the 17-spirolactone and are less structurally transferable. Overall, F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule was retrieved; the decision relies on close analogues with moderate Morgan similarity.",
    "First-pass metabolism differences between 17-spirolactone steroids and 17-acetate/ketone steroids are inferred but not directly quantified for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

